use vstd::prelude::*;

verus! {

spec fn rev_seq(s: Seq<i8>) -> Seq<i8> {
    s.reverse()
}

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev@ == rev_seq(s@),
        rev.len() == s.len(),
{
    let n = s.len();
    let mut rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == s.len(),
            // `i` ranges over 0..=n in this rev loop; rev contains the suffix already processed
            0 <= i <= n,
            rev@ == rev_seq(s@.subrange((i + 1) as int, n as int)),
            rev.len() == n - (i + 1),
        decreases i,
    {
        rev.push(s[i]);

        assert(rev@ == rev_seq(s@.subrange(i as int, n as int))) by {
            // From the invariant, before push:
            //   rev@ = reverse(s[(i+1)..n])
            // After push(s[i]), we have:
            //   rev@ = reverse(s[(i+1)..n]) + [s[i]]
            // which equals reverse(s[i..n]).
            let suf = s@.subrange((i + 1) as int, n as int);
            let suf2 = s@.subrange(i as int, n as int);

            assert(suf2 == suf.push(s@[i as int]));
            assert(rev_seq(suf2) == rev_seq(suf).push(s@[i as int]));
        };
    }
    rev
}

} // verus!

